import re
import urllib.parse
import requests
import json
def task_func(myString, API_KEY):
    url_pattern = r'https?://[^\s]+'
    urls = re.findall(url_pattern, myString)
    result = {}
    for url in urls:
        parsed = urllib.parse.urlparse(url)
        domain = parsed.netloc
        api_url = f"http://ip-api.com/json/{domain}?fields=status,country,region,city,lat,lon,isp,org,as,query&key={API_KEY}"
        try:
            response = requests.get(api_url)
            if response.status_code == 200:
                result[domain] = json.loads(response.text)
            else:
                result[domain] = None
        except:
            result[domain] = None
    return result

