import re
import json
from collections import Counter

def task_func(json_str, top_n=10):
    def extract_strings(obj):
        strings = []
        if isinstance(obj, str):
            strings.append(obj)
        elif isinstance(obj, dict):
            for v in obj.values():
                strings.extend(extract_strings(v))
        elif isinstance(obj, list):
            for item in obj:
                strings.extend(extract_strings(item))
        return strings

    data = json.loads(json_str)
    all_strings = extract_strings(data)
    url_pattern = r'https?://(?:[-\w.]|(?:%[\da-fA-F]{2}))+[/\w\.\-?=&%]*'
    urls = []
    for s in all_strings:
        urls.extend(re.findall(url_pattern, s))
    url_counts = Counter(urls)
    top_urls = url_counts.most_common(top_n)
    return dict(top_urls)

import pandas as pd
import os
import json
from collections import Counter
def task_func(json_dir_path, word_count):
    all_words = []
    for filename in os.listdir(json_dir_path):
        if filename.endswith('.json'):
            file_path = os.path.join(json_dir_path, filename)
            with open(file_path, 'r') as f:
                data = json.load(f)
                if 'text' in data:
                    words = data['text'].lower().split()
                    all_words.extend(words)
    counter = Counter(all_words)
    return counter.most_common(word_count)

